CREATE TABLE public.institution_role_events(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,institution_id uuid NOT NULL,actor_id uuid NOT NULL,user_id uuid NOT NULL,previous_role text,new_role text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.institution_role_events TO authenticated; GRANT ALL ON public.institution_role_events TO service_role;
ALTER TABLE public.institution_role_events ENABLE ROW LEVEL SECURITY;
CREATE POLICY role_event_read ON public.institution_role_events FOR SELECT TO authenticated USING(public.can_manage_student_records(institution_id));
CREATE FUNCTION public.lead_institution_members(_inst uuid) RETURNS TABLE(user_id uuid,display_name text,email text,member_role public.institution_role) LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.can_manage_student_records(_inst) THEN RAISE EXCEPTION 'Sin permiso' USING ERRCODE='42501'; END IF; RETURN QUERY SELECT m.user_id,coalesce(p.display_name,''),u.email::text,m.member_role FROM public.institution_members m JOIN auth.users u ON u.id=m.user_id LEFT JOIN public.profiles p ON p.id=m.user_id WHERE m.institution_id=_inst ORDER BY m.member_role,u.email; END $$;
REVOKE ALL ON FUNCTION public.lead_institution_members(uuid) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.lead_institution_members(uuid) TO authenticated;
CREATE FUNCTION public.lead_set_institution_member(_inst uuid,_email text,_role public.institution_role) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE uid uuid; oldrole public.institution_role; BEGIN IF NOT public.can_manage_student_records(_inst) THEN RAISE EXCEPTION 'Sin permiso' USING ERRCODE='42501'; END IF; IF _role IN ('direccion','subdireccion') THEN RAISE EXCEPTION 'Designación reservada a Max' USING ERRCODE='42501'; END IF; IF lower(btrim(_email)) NOT LIKE '%@gmail.com' THEN RAISE EXCEPTION 'Use una cuenta Gmail confirmada'; END IF; SELECT id INTO uid FROM auth.users WHERE lower(email)=lower(btrim(_email)) AND email_confirmed_at IS NOT NULL; IF uid IS NULL THEN RAISE EXCEPTION 'Cuenta confirmada no encontrada'; END IF; IF uid=auth.uid() THEN RAISE EXCEPTION 'No puede modificar su propio rol' USING ERRCODE='42501'; END IF; SELECT member_role INTO oldrole FROM public.institution_members WHERE institution_id=_inst AND user_id=uid FOR UPDATE; IF oldrole IN ('direccion','subdireccion') OR public.has_role(uid,'admin') THEN RAISE EXCEPTION 'Autoridad protegida' USING ERRCODE='42501'; END IF; INSERT INTO public.institution_members(institution_id,user_id,member_role,verified_by) VALUES(_inst,uid,_role,auth.uid()) ON CONFLICT(institution_id,user_id) DO UPDATE SET member_role=excluded.member_role,verified_by=auth.uid(); INSERT INTO public.institution_role_events(institution_id,actor_id,user_id,previous_role,new_role) VALUES(_inst,auth.uid(),uid,oldrole::text,_role::text); RETURN uid; END $$;
REVOKE ALL ON FUNCTION public.lead_set_institution_member(uuid,text,public.institution_role) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.lead_set_institution_member(uuid,text,public.institution_role) TO authenticated;